INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Hypothalamic-Pituitary Axis','easy','flashcard','What is the name of the vascular structure that carries hypothalamic releasing hormones to the anterior pituitary?','["The hypophyseal portal blood system (hypothalamo-hypophyseal portal circulation) — carries releasing/inhibiting hormones from the median eminence to anterior pituitary sinusoids."]','A','This portal system allows very high local hormone concentrations at the anterior pituitary without systemic dilution.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Hypothalamic-Pituitary Axis','easy','flashcard','Name the 6 hormones secreted by the anterior pituitary.','["GH (somatotrophs), TSH (thyrotrophs), ACTH (corticotrophs), FSH and LH (gonadotrophs), and Prolactin (lactotrophs). Mnemonic: "GTA FSH PRL""]','A','Posterior pituitary stores ADH and oxytocin but these are synthesized in the hypothalamus.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Hypothalamic-Pituitary Axis','medium','flashcard','What is TRH and which two anterior pituitary hormones does it stimulate?','["TRH (thyrotropin-releasing hormone) is a tripeptide from the hypothalamus that stimulates release of TSH (from thyrotrophs) and prolactin (from lactotrophs)."]','A','TRH elevation in hypothyroidism explains why hypothyroid patients can develop hyperprolactinemia and galactorrhea.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Hypothalamic-Pituitary Axis','medium','flashcard','Define "long-loop" negative feedback in the HPA axis.','["Long-loop feedback: the peripheral end-organ hormone (cortisol) feeds back to inhibit BOTH CRH release from the hypothalamus AND ACTH release from the anterior pituitary corticotrophs."]','A','Exogenous glucocorticoids suppress the HPA axis via this mechanism, causing iatrogenic adrenal insufficiency on abrupt withdrawal.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Hypothalamic-Pituitary Axis','medium','flashcard','What is the role of dopamine in prolactin regulation?','["Dopamine (prolactin-inhibiting hormone, PIH) released from tuberoinfundibular neurons tonically inhibits prolactin secretion via D2 receptors on lactotrophs. Loss of inhibition → hyperprolactinemia."]','A','Drugs that block dopamine receptors (antipsychotics, metoclopramide) cause hyperprolactinemia as a side effect.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Hypothalamic-Pituitary Axis','easy','flashcard','Where are ADH and oxytocin synthesized and where are they stored/released?','["Both synthesized in hypothalamic nuclei (ADH in supraoptic nucleus; oxytocin in paraventricular nucleus). Transported along axons to the posterior pituitary where they are stored and released."]','A','The posterior pituitary (neurohypophysis) does NOT synthesize hormones — it is merely a storage and release depot.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Hypothalamic-Pituitary Axis','medium','flashcard','What is the sequence: GnRH → anterior pituitary → gonad → feedback?','["GnRH (arcuate nucleus, pulsatile) → FSH + LH (gonadotrophs) → ovary/testis → estradiol/testosterone/inhibin B → negative feedback on GnRH and gonadotrophs (long-loop). Testosterone also inhibits LH preferentially; inhibin B inhibits FSH specifically."]','A','Pulsatile GnRH is essential — continuous GnRH downregulates receptors and suppresses FSH/LH (exploited therapeutically).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Hypothalamic-Pituitary Axis','hard','flashcard','Distinguish "short-loop" from "ultra-short-loop" feedback in the hypothalamic-pituitary system.','["Short-loop: anterior pituitary hormones (e.g., GH, ACTH) feed back to inhibit their own hypothalamic releasing hormone neurons. Ultra-short loop: hypothalamic releasing hormones inhibit their own secreting neurons (autocrine/paracrine self-inhibition)."]','A','Long-loop = peripheral effector hormone → hypothalamus/pituitary. Short-loop = pituitary hormone → hypothalamus. Ultra-short = hypothalamic neuron → itself.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Hypothalamic-Pituitary Axis','medium','flashcard','What is GHRH and what inhibits GH release from the hypothalamus?','["GHRH (growth hormone-releasing hormone) from the arcuate nucleus stimulates GH secretion. Somatostatin (from the periventricular nucleus) inhibits GH. Ghrelin (from stomach) also stimulates GH via GHS-R1a."]','A','GH secretion is pulsatile with the largest pulse during slow-wave sleep (stage 3-4). IGF-1 provides negative feedback on both GHRH and somatotrophs.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Hypothalamic-Pituitary Axis','hard','flashcard','CRH is released from where and acts on which cell type via which receptor and second messenger?','["CRH is released from parvocellular neurons of the paraventricular nucleus (PVN). Acts on corticotrophs of the anterior pituitary via CRH-R1 (Gs-coupled GPCR) → increases cAMP → PKA activation → ACTH synthesis and secretion."]','A','CRH is also released during stress (psychological, inflammatory, hypoglycemic). Arginine vasopressin (AVP) potentiates CRH-induced ACTH release synergistically.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Thyroid Physiology','easy','flashcard','What are MIT and DIT, and how do they combine to form T3 and T4?','["MIT = monoiodotyrosine (1 iodine); DIT = diiodotyrosine (2 iodines). MIT + DIT = T3 (3 iodines). DIT + DIT = T4 (4 iodines). Coupling is catalyzed by thyroid peroxidase (TPO)."]','A','Both coupling and organification (iodination of tyrosines) are catalyzed by TPO. Antithyroid drugs (PTU, methimazole) inhibit TPO.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Thyroid Physiology','easy','flashcard','What is the half-life of T4 vs T3, and why does T4 have a longer half-life?','["T4 half-life ≈ 7 days; T3 half-life ≈ 1 day. T4s longer half-life is due to ~99% protein binding (mainly to TBG, transthyretin, albumin), providing a large circulating reservoir that slows clearance."]','A','Free T4 (0.04%) and free T3 (0.4%) are the biologically active fractions. Total T4 is high in pregnancy (elevated TBG) even though free T4 is normal.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Thyroid Physiology','medium','flashcard','What is the NIS and what drives iodide uptake into thyroid follicular cells?','["NIS (sodium-iodide symporter) is a basolateral membrane transporter that cotransports 2 Na+ with 1 I- into the follicular cell. The Na+ gradient (maintained by Na-K-ATPase) provides the energy for active iodide accumulation."]','A','Iodide concentration inside thyroid cells can be 20-50x higher than plasma. TSH upregulates NIS expression. Radioactive iodine (RAI) uses NIS for thyroid imaging and ablation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Thyroid Physiology','medium','flashcard','Describe the sequence of thyroid hormone synthesis from iodide intake to T4 secretion.','["1. Iodide trapped by NIS (basolateral). 2. Pendrin transports I- into colloid (apical). 3. TPO oxidizes I- to I2 and organifies onto thyroglobulin tyrosines (MIT, DIT). 4. TPO couples MIT+DIT (T3) and DIT+DIT (T4) on thyroglobulin. 5. TSH stimulates endocytosis of thyroglobulin colloid. 6. Lysosomes cleave T3/T4 from thyroglobulin. 7. T3/T4 released into blood."]','A','MIT and DIT residues not incorporated are deiodinated intracellularly and iodide is recycled.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Thyroid Physiology','medium','flashcard','How does T3 exert its cellular effects?','["T3 (lipophilic) diffuses into cells, binds nuclear thyroid hormone receptors (TRα, TRβ). The T3-receptor complex binds thyroid hormone response elements (TREs) as heterodimers with RXR, regulating gene transcription. Effects include increased basal metabolic rate, Na-K-ATPase expression, and adrenergic receptor sensitivity."]','A','T4 is largely a prohormone converted to active T3 by type 1 and type 2 iodothyronine deiodinases in peripheral tissues. Reverse T3 (rT3) is an inactive metabolite.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Thyroid Physiology','easy','flashcard','What is the normal TSH range and why is TSH the most sensitive marker of thyroid dysfunction?','["Normal TSH: 0.5-4.5 mIU/L. TSH is the most sensitive test because pituitary thyrotrophs amplify even tiny changes in free T4/T3 — a small decrease in free T4 causes a large rise in TSH, making subclinical dysfunction detectable before symptoms emerge."]','A','In primary hypothyroidism: TSH high, T4 low. In hyperthyroidism: TSH low (suppressed), T4 high. In secondary hypothyroidism: TSH low or inappropriately normal, T4 low.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Thyroid Physiology','medium','flashcard','What percentage of thyroid output is T4 vs T3, and what happens to most T4 in peripheral tissues?','["The thyroid secretes ~90% T4 and ~10% T3. In peripheral tissues, ~80% of circulating T3 is derived from 5-deiodination of T4 by type 1 deiodinase (liver, kidney) and type 2 deiodinase (brain, pituitary, thyroid)."]','A','Type 3 deiodinase inactivates T4 (→ reverse T3) and T3 (→ T2). In critical illness, preferential type 3 activity causes low T3 syndrome ("sick euthyroid").','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Thyroid Physiology','hard','flashcard','What is the Wolf-Chaikoff effect and the Jod-Basedow phenomenon?','["Wolff-Chaikoff effect: acute high iodide load transiently inhibits thyroid hormone synthesis (organification block) — used therapeutically pre-thyroidectomy (Lugols iodine). Jod-Basedow: excess iodide triggers hyperthyroidism in patients with autonomous thyroid nodules or latent Graves disease."]','A','The Wolff-Chaikoff effect is transient (escape occurs in ~10 days via NIS downregulation). Amiodarone (40% iodine by weight) can cause either hypothyroidism (Wolff-Chaikoff) or hyperthyroidism (Jod-Basedow).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Thyroid Physiology','medium','flashcard','TSH acts through which receptor and second messenger to stimulate thyroid function?','["TSH binds TSHR (TSH receptor) — a Gs-coupled GPCR on thyroid follicular cells. Activation increases cAMP via adenylyl cyclase. cAMP-PKA signaling stimulates all steps of thyroid hormone synthesis and secretion, and promotes thyroid cell proliferation (goitrogenic effect)."]','A','In Graves disease, TSH-receptor antibodies (TRAb) stimulate TSHR constitutively, causing hyperthyroidism and diffuse goiter.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Thyroid Physiology','hard','flashcard','Describe the regulation of thyroid hormone secretion at all three levels (TRH-TSH-T3/T4 axis).','["TRH (hypothalamus) → TSH (anterior pituitary thyrotrophs) → T3/T4 (thyroid follicular cells). Negative feedback: T3/T4 inhibit TSH secretion (pituitary, primary site) and TRH (hypothalamus, secondary). T3 reduces TRH receptor on thyrotrophs and decreases TSHβ subunit gene expression."]','A','Free T3 (converted from T4 locally in pituitary by type 2 deiodinase) is the primary feedback signal at the pituitary level, not circulating T3.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Adrenal Cortex','easy','flashcard','Name the three zones of the adrenal cortex and their respective hormone products.','["GFR from outside in: Zona Glomerulosa (outermost) → Aldosterone (mineralocorticoid). Zona Fasciculata (middle) → Cortisol (glucocorticoid). Zona Reticularis (innermost) → Androgens (DHEA, androstenedione). Mnemonic: "GFR — Salt, Sugar, Sex""]','A','All three zones produce steroids derived from cholesterol. Only the glomerulosa expresses CYP11B2 (aldosterone synthase); only the fasciculata/reticularis express CYP17A1.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Adrenal Cortex','easy','flashcard','What is the rate-limiting step in adrenocortical steroidogenesis?','["The rate-limiting step is transport of cholesterol from the outer to the inner mitochondrial membrane by StAR (steroidogenic acute regulatory protein). CYP11A1 then converts cholesterol to pregnenolone on the inner membrane."]','A','ACTH acutely increases StAR expression via cAMP-PKA signaling. StAR mutations cause lipoid congenital adrenal hyperplasia (no steroid production).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Adrenal Cortex','medium','flashcard','What are the primary regulators of aldosterone secretion?','["Primary regulators: (1) Angiotensin II (most potent — via RAAS activation from low BP/volume). (2) Hyperkalemia (directly stimulates glomerulosa cells). ACTH provides a minor permissive effect. Low sodium stimulates aldosterone indirectly via renin-angiotensin."]','A','Angiotensin II acts on glomerulosa cells via AT1 receptor (Gq-IP3/DAG pathway), increasing CYP11B2 expression. K+ depolarizes glomerulosa cells, increasing Ca2+ influx and CYP11B2 activity.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Adrenal Cortex','medium','flashcard','Describe the mechanism of aldosterone action in the principal cells of the collecting duct.','["Aldosterone (steroid) diffuses into principal cells, binds cytoplasmic mineralocorticoid receptor (MR). The MR-aldosterone complex translocates to the nucleus, increasing transcription of ENaC (epithelial sodium channel, apical) and Na-K-ATPase (basolateral). Net: increased Na+ reabsorption, K+ secretion, H+ secretion."]','A','Spironolactone and eplerenone are competitive MR antagonists (K+-sparing diuretics). Cortisol can also bind MR; 11β-HSD2 in collecting duct inactivates cortisol to cortisone, protecting MR specificity.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Adrenal Cortex','medium','flashcard','What is the diurnal rhythm of cortisol and what drives it?','["Cortisol peaks at approximately 6-8 AM (just before/after waking) and reaches its nadir around midnight. This rhythm is driven by circadian variation in CRH and ACTH secretion from the suprachiasmatic nucleus (SCN) via the PVN-CRH axis."]','A','Normal morning cortisol: 5-25 mcg/dL. Disruption of diurnal rhythm (e.g., night shift work, Cushings) is detected by midnight salivary cortisol. Loss of diurnal rhythm is a hallmark of Cushings syndrome.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Adrenal Cortex','easy','flashcard','Name 4 major metabolic effects of cortisol.','["1. Increased hepatic gluconeogenesis (raises blood glucose). 2. Increased protein catabolism in muscle (substrate for gluconeogenesis). 3. Lipolysis in adipose tissue (increases free fatty acids). 4. Anti-inflammatory and immunosuppressive effects. Also: decreased peripheral glucose uptake (anti-insulin/diabetogenic)."]','A','Cushings syndrome manifests these effects as: hyperglycemia, muscle wasting, central obesity (redistribution), hypertension, and immunosuppression.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Adrenal Cortex','medium','flashcard','What is 21-hydroxylase deficiency and what are its hormonal consequences?','["21-hydroxylase (CYP21A2) deficiency blocks conversion of 17-OH progesterone → 11-deoxycortisol (cortisol pathway) and progesterone → 11-deoxycorticosterone (aldosterone pathway). Consequences: cortisol deficiency → high ACTH → adrenal hyperplasia + androgen excess. Most common cause of congenital adrenal hyperplasia (CAH)."]','A','Classic CAH: salt-wasting (no aldosterone) + virilization (androgen excess). 17-OH progesterone is the diagnostic marker. Treatment: glucocorticoid replacement (suppresses excess ACTH/androgens).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Adrenal Cortex','hard','flashcard','Distinguish between primary, secondary, and tertiary adrenal insufficiency.','["Primary (Addisons disease): adrenal gland itself is destroyed (autoimmune, TB, etc.) — cortisol LOW, ACTH HIGH (no feedback), aldosterone LOW, hyperpigmentation (high ACTH/MSH). Secondary: anterior pituitary fails to produce ACTH — cortisol LOW, ACTH LOW, aldosterone usually preserved. Tertiary: hypothalamic CRH deficiency — cortisol LOW, ACTH LOW, usually from exogenous glucocorticoid withdrawal."]','A','Only primary AI has mineralocorticoid deficiency (aldosterone low → hyponatremia, hyperkalemia, volume depletion). Secondary/tertiary AI spares aldosterone (regulated by RAAS, not ACTH).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Adrenal Cortex','medium','flashcard','How does cortisol exert negative feedback on the HPA axis?','["Cortisol acts on glucocorticoid receptors (GR) in hypothalamic PVN neurons (reducing CRH synthesis) and in anterior pituitary corticotrophs (reducing ACTH synthesis and secretion via decreased pro-opiomelanocortin/POMC transcription). Fast feedback (minutes) via non-genomic mechanisms; slow feedback (hours-days) via genomic GR signaling."]','A','Synthetic glucocorticoids (dexamethasone) suppress the HPA axis and ACTH. Failure to suppress with low-dose dexamethasone is screening for Cushings syndrome.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Adrenal Cortex','hard','flashcard','What is the CYP11B1 vs CYP11B2 distinction and why is it clinically important?','["CYP11B1 (11β-hydroxylase): converts 11-deoxycortisol to cortisol in the zona fasciculata. CYP11B2 (aldosterone synthase): converts corticosterone to aldosterone, expressed ONLY in zona glomerulosa. CYP11B1 deficiency → CAH with hypertension (11-deoxycorticosterone accumulates as a weak mineralocorticoid). CYP11B2 deficiency → isolated aldosterone deficiency (type 2 CMO)."]','A','This explains why 21-hydroxylase deficiency causes salt-wasting but 11β-hydroxylase deficiency causes hypertension despite impaired cortisol — different metabolite accumulation patterns.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Adrenal Medulla','easy','flashcard','What is the biosynthetic pathway for catecholamines in the adrenal medulla?','["Tyrosine → L-DOPA (TH, tyrosine hydroxylase — rate-limiting) → Dopamine (AADC, aromatic amino acid decarboxylase) → Norepinephrine (DBH, dopamine β-hydroxylase, in granule) → Epinephrine (PNMT, phenylethanolamine N-methyltransferase, requires cortisol)."]','A','PNMT converts NE to epinephrine in the cytosol; the reaction requires high local cortisol concentrations delivered via intra-adrenal portal circulation from the cortex to the medulla.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Adrenal Medulla','easy','flashcard','What proportion of adrenal medulla secretion is epinephrine vs norepinephrine?','["Approximately 80% epinephrine, 20% norepinephrine. The high proportion of epinephrine (vs peripheral sympathetic nerves that release mostly NE) reflects high PNMT activity maintained by intra-adrenal cortisol."]','A','This ratio shifts in pheochromocytoma, where extra-adrenal (paraganglioma) tumors may secrete predominantly NE (lacking PNMT due to absent cortisol).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Adrenal Medulla','medium','flashcard','Chromaffin cells are stimulated to secrete catecholamines by which neurotransmitter and receptor?','["Preganglionic sympathetic nerve fibers release acetylcholine (ACh), which acts on nicotinic acetylcholine receptors (nAChR, specifically the ganglionic type N2) on chromaffin cells. ACh triggers calcium influx and vesicle exocytosis."]','A','Chromaffin cells are analogous to postganglionic sympathetic neurons but secrete hormones into blood rather than a synapse. ACh also triggers Ca2+ release from ER via muscarinic receptors.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Adrenal Medulla','medium','flashcard','What are the major metabolic pathways for catecholamine breakdown and the resulting urinary metabolites?','["MAO (monoamine oxidase) and COMT (catechol-O-methyltransferase) metabolize catecholamines. Key metabolites: Epinephrine → Metanephrine → VMA (vanillylmandelic acid). Norepinephrine → Normetanephrine → VMA. Dopamine → Homovanillic acid (HVA). Plasma free metanephrines are most sensitive for pheochromocytoma."]','A','MAO is intracellular (mitochondrial); COMT is extracellular/cytosolic. Sequential action produces VMA as a final common metabolite.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Adrenal Medulla','easy','flashcard','What is the plasma half-life of catecholamines and what accounts for this?','["Plasma half-life of catecholamines is 2-3 minutes. Rapid clearance is due to: (1) neuronal reuptake (NET/DAT), (2) MAO-mediated oxidation, and (3) COMT-mediated methylation. This explains why catecholamine effects are brief and require continuous secretion."]','A','Urine metanephrines (24h collection or spot) are more stable markers. Plasma free metanephrines are the most sensitive test for pheochromocytoma.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Adrenal Medulla','medium','flashcard','Distinguish the receptor profiles of epinephrine vs norepinephrine.','["Epinephrine: α1 (vasoconstriction), β1 (increased HR/contractility), β2 (bronchodilation, skeletal muscle vasodilation). Norepinephrine: predominantly α1 (peripheral vasoconstriction), minimal β2 activity. NE causes net increase in peripheral resistance; Epi causes mixed vasodilation (skeletal) and vasoconstriction (skin/viscera)."]','A','This explains why epinephrine (not NE) is used for anaphylaxis — its β2 effect reverses bronchospasm and β1 supports cardiac output.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Adrenal Medulla','medium','flashcard','What is chromogranin A and what is its clinical significance?','["Chromogranin A (CgA) is an acidic protein co-stored with catecholamines in chromaffin granules and co-released during exocytosis. It is a pan-neuroendocrine biomarker measurable in plasma — elevated in pheochromocytoma, carcinoid tumors, and other NETs."]','A','CgA levels correlate with neuroendocrine tumor (NET) burden. False elevations occur with proton pump inhibitor (PPI) use (hypergastrinemia) and renal failure.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Adrenal Medulla','hard','flashcard','What are the cardiovascular effects of epinephrine at low vs high doses?','["Low dose epinephrine: β2 > α1 → vasodilation in skeletal muscle beds → decreased total peripheral resistance → decreased diastolic BP; β1 → increased HR and contractility → increased systolic BP. High dose: α1 dominates → vasoconstriction → increased peripheral resistance → increased both systolic and diastolic BP."]','A','This biphasic dose-response is clinically relevant: low-dose "physiologic" epinephrine (during exercise/stress) preferentially vasodilates muscle; pharmacologic epinephrine doses cause vasoconstriction.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Adrenal Medulla','medium','flashcard','What is pheochromocytoma and what triad of symptoms does it cause?','["Pheochromocytoma is a catecholamine-secreting tumor of adrenal medullary chromaffin cells (extra-adrenal = paraganglioma). Classic triad: episodic Headache, palpitations (tachycardia), and diaphoresis (sweating) — the "5 Hs": Hypertension, Headache, palpitations (Heart racing), Hyperhidrosis, Hypermetabolism."]','A','Diagnosis: plasma free metanephrines (most sensitive). Imaging: CT/MRI. Treatment: surgical resection after alpha-blockade (phenoxybenzamine) BEFORE beta-blockade.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Adrenal Medulla','hard','flashcard','Why must alpha-blockade be established BEFORE beta-blockade in pheochromocytoma management?','["Administering a beta-blocker first in pheochromocytoma blocks β2-mediated vasodilation, leaving α1-mediated vasoconstriction unopposed → paradoxical severe hypertensive crisis. Alpha-blockade first (phenoxybenzamine) prevents this by blocking vasoconstriction; then beta-blockers can safely manage tachycardia."]','A','This reflects the dominance of α1 vasoconstriction when β2 vasodilation is blocked. Alpha-blockers (prazosin, doxazosin, phenoxybenzamine) are given for 1-2 weeks pre-operatively with volume repletion.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Pancreatic Endocrine Function','easy','flashcard','Name the four major cell types in the islets of Langerhans and their hormone products.','["Beta cells (~70%): insulin + amylin. Alpha cells (~20%): glucagon. Delta cells (~5%): somatostatin. PP cells (~5%): pancreatic polypeptide (PP). The islet architecture places beta cells centrally surrounded by alpha and delta cells, enabling paracrine regulation."]','A','Mnemonic: BAD PP — Beta, Alpha, Delta, PP cells. Insulin inhibits glucagon; somatostatin inhibits both.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Pancreatic Endocrine Function','easy','flashcard','Describe the processing of preproinsulin to insulin.','["Preproinsulin (synthesized in RER) → signal peptide cleaved → proinsulin (folded, disulfide bonds formed). In secretory granules, PC1/3 and PC2 proteases cleave connecting C-peptide → mature insulin (A chain + B chain linked by disulfide bonds) + C-peptide (equimolar)."]','A','C-peptide has a longer half-life than insulin and is not cleared hepatically — useful for measuring endogenous insulin production (absent in T1DM, exogenous insulin administration).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Pancreatic Endocrine Function','medium','flashcard','Describe the glucose-stimulated insulin secretion (GSIS) pathway in beta cells.','["Glucose enters via high-Km GLUT2 → glycolysis/oxidative phosphorylation → increased ATP:ADP ratio → closes KATP channels (Kir6.2/SUR1) → membrane depolarization → opens voltage-gated Ca2+ channels → Ca2+ influx → triggers insulin granule exocytosis."]','A','Sulfonylureas (glibenclamide) close KATP channels independently of glucose, stimulating insulin secretion. GLP-1 amplifies GSIS by increasing cAMP, which sensitizes the secretory machinery to calcium.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Pancreatic Endocrine Function','medium','flashcard','What are the major actions of insulin on glucose metabolism in liver, muscle, and adipose?','["Liver: inhibits gluconeogenesis (PEPCK, G6Pase) and glycogenolysis; stimulates glycogen synthesis and lipogenesis. Muscle: GLUT4 translocation → increased glucose uptake; glycogen synthesis; protein synthesis. Adipose: GLUT4-mediated glucose uptake; inhibits HSL (anti-lipolysis); lipogenesis. Net: lower blood glucose."]','A','Insulin activates PI3K-Akt signaling (metabolic effects) and MAPK pathway (growth effects). Akt phosphorylates AS160 → GLUT4 vesicle fusion with plasma membrane.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Pancreatic Endocrine Function','easy','flashcard','What is the insulin receptor and what immediate signaling events does insulin binding trigger?','["The insulin receptor is a tetrameric receptor tyrosine kinase (2 α subunits + 2 β subunits linked by disulfide bonds). Insulin binding → conformational change → trans-autophosphorylation of β subunit tyrosines → activates IRS-1/IRS-2 phosphorylation → PI3K-Akt and MAPK cascades."]','A','Downstream: PI3K-Akt mediates metabolic effects (GLUT4 translocation, glycogen synthesis, lipogenesis, anti-lipolysis). MAPK mediates mitogenic effects (cell growth, proliferation).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Pancreatic Endocrine Function','medium','flashcard','What are glucagons primary actions in the liver and what triggers its secretion?','["Glucagon (alpha cells) acts via Gs-cAMP-PKA in hepatocytes to: (1) activate glycogen phosphorylase (glycogenolysis), (2) inhibit glycogen synthase, (3) increase PEPCK/G6Pase transcription (gluconeogenesis), (4) stimulate ketogenesis (promotes fatty acid oxidation). Secretion triggered by: hypoglycemia, amino acids, sympathetic activation, and inhibited by hyperglycemia and insulin."]','A','Glucagon is the primary counter-regulatory hormone for hypoglycemia. In T1DM, the alpha cell glucagon response to hypoglycemia is often impaired, increasing hypoglycemia risk.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Pancreatic Endocrine Function','medium','flashcard','What are the incretins and what is the "incretin effect"?','["Incretins are gut hormones that amplify insulin secretion in response to oral nutrient intake: GLP-1 (from L cells of ileum/colon) and GIP (from K cells of duodenum/jejunum). The "incretin effect": oral glucose evokes 2-3x more insulin than equivalent IV glucose. Both act via Gs-cAMP on beta cells in a glucose-dependent manner."]','A','DPP-4 rapidly degrades GLP-1 (half-life ~2 min). Pharmacologic targets: GLP-1 receptor agonists (semaglutide, liraglutide) and DPP-4 inhibitors (sitagliptin, saxagliptin).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Pancreatic Endocrine Function','hard','flashcard','Why does pancreatic delta cell somatostatin inhibit both alpha and beta cells?','["Delta cell somatostatin acts in a paracrine manner on adjacent alpha cells (SSTR2) and beta cells (SSTR5), inhibiting their cAMP signaling (via Gi-coupled receptors) and reducing hormone secretion. This creates a local "off switch" for both insulin and glucagon after their initial secretion."]','A','Systemic somatostatin (octreotide/lanreotide) also inhibits GH, TSH, CCK, secretin, and gastrin — exploited therapeutically for acromegaly, neuroendocrine tumors, and variceal bleeding.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Pancreatic Endocrine Function','easy','flashcard','What is the normal fasting insulin level and what is insulins plasma half-life?','["Normal fasting insulin: 5-20 μU/mL (35-145 pmol/L). Plasma half-life of insulin: approximately 5-8 minutes. Rapid clearance occurs due to insulin-degrading enzyme (IDE/insulinase) in the liver (~50% first-pass), kidney, and peripheral tissues."]','A','The short half-life means insulin must be secreted continuously to maintain glucose homeostasis. Exogenous insulin formulations use structural modifications (protamine, zinc crystals, amino acid substitutions) to extend duration.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Pancreatic Endocrine Function','hard','flashcard','Explain the mechanism by which amylin (IAPP) complements insulins glucose-lowering effect.','["Amylin (islet amyloid polypeptide, IAPP) is co-secreted with insulin from beta cells. Amylin: (1) suppresses post-meal glucagon secretion from alpha cells, (2) slows gastric emptying (reducing glucose flux), (3) reduces appetite via central signals. Together with insulin, amylin limits post-meal blood glucose excursions."]','A','Amylin is the protein that aggregates in islets in T2DM (islet amyloid). Pramlintide is a synthetic amylin analog approved as an adjunct to insulin in T1DM and T2DM.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Calcium & Phosphate Regulation','easy','flashcard','What are the three major hormones regulating calcium homeostasis and where are they produced?','["PTH: chief cells of parathyroid glands (raises Ca2+). Calcitriol (1,25(OH)2D3): active vitamin D, produced in kidney proximal tubule (raises Ca2+). Calcitonin: parafollicular C cells of thyroid (lowers Ca2+). PTH and calcitriol are the dominant regulators."]','A','Calcitonins physiologic role in humans is minor compared to PTH and vitamin D. Calcitonin is clinically useful for acute hypercalcemia (rapid onset) and Pagets disease.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Calcium & Phosphate Regulation','easy','flashcard','What stimulates PTH secretion and how does the CaSR regulate this?','["LOW ionized Ca2+ is the primary stimulus for PTH secretion. The CaSR (calcium-sensing receptor) on parathyroid chief cells is a Gq-coupled GPCR that senses ionized Ca2+. When Ca2+ is HIGH, CaSR is activated → inhibits PTH secretion. When Ca2+ is LOW, CaSR activity falls → PTH secretion increases."]','A','CaSR is the "thermostat" for calcium homeostasis. Calcimimetics (cinacalcet) activate CaSR to suppress PTH — used for secondary hyperparathyroidism in CKD and parathyroid carcinoma.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Calcium & Phosphate Regulation','medium','flashcard','Describe all renal effects of PTH on calcium, phosphate, and vitamin D metabolism.','["PTH acts via Gs-cAMP on: (1) Distal tubule/DCT: increases Ca2+ reabsorption via TRPV5. (2) Proximal tubule: DECREASES phosphate reabsorption (inhibits NaPi-IIa/IIc — "phosphaturia"). (3) Proximal tubule: INCREASES 1-alpha hydroxylase (CYP27B1) activity → more calcitriol synthesis."]','A','Net renal effects of PTH: hypocalciuria (saves Ca2+), hyperphosphaturia (wastes PO4-), and increased calcitriol. In hyperparathyroidism: hypercalcemia + hypophosphatemia + hypercalciuria.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Calcium & Phosphate Regulation','medium','flashcard','Outline the vitamin D activation pathway from skin to active calcitriol.','["1. UV-B light in skin converts 7-dehydrocholesterol → cholecalciferol (vitamin D3). 2. Liver CYP2R1/CYP27A1: 25-hydroxylation → 25(OH)D3 (calcidiol — the storage form measured in serum). 3. Kidney proximal tubule CYP27B1 (1-alpha hydroxylase): 1-hydroxylation → 1,25(OH)2D3 (calcitriol — active form)."]','A','CYP27B1 is upregulated by: PTH, low Ca2+, low PO4-. Inhibited by: FGF-23, high Ca2+, high calcitriol (self-limiting). CYP24A1 inactivates calcitriol (1,25 → 24,25-dihydroxyvitamin D).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Calcium & Phosphate Regulation','easy','flashcard','What are the intestinal effects of calcitriol (active vitamin D)?','["Calcitriol acts on intestinal enterocytes (nuclear VDR receptor) to increase expression of: TRPV6 (apical Ca2+ channel), calbindin-D9k (intracellular Ca2+ carrier), and PMCA1b/NCX (basolateral Ca2+ exporters). Also increases intestinal phosphate absorption (NaPi-IIb). Net: increased dietary Ca2+ and PO4- absorption."]','A','Vitamin D deficiency impairs intestinal Ca2+ absorption → secondary hyperparathyroidism → bone resorption (osteomalacia in adults, rickets in children). Serum 25(OH)D3 <20 ng/mL = deficiency.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Calcium & Phosphate Regulation','medium','flashcard','Explain the role of RANKL/RANK/OPG in PTH-mediated bone resorption.','["PTH acts on osteoblasts (PTH1R → Gs-cAMP) → increases RANKL expression and decreases OPG (osteoprotegerin, a decoy RANK receptor) secretion. RANKL binds RANK on osteoclast precursors → differentiation into mature osteoclasts → bone resorption. OPG normally blocks this by binding RANKL."]','A','Denosumab is a monoclonal antibody against RANKL — inhibits osteoclastogenesis. Teriparatide (intermittent PTH analog) paradoxically BUILDS bone when given intermittently (anabolic window) via net stimulation of osteoblast activity.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Calcium & Phosphate Regulation','medium','flashcard','What is FGF-23, where is it produced, and what are its main effects?','["FGF-23 (fibroblast growth factor 23) is produced by osteocytes and osteoblasts in bone in response to elevated phosphate and calcitriol. Effects on kidney (via FGFR1-klotho complex): (1) inhibits NaPi-IIa/IIc → phosphaturia, (2) inhibits CYP27B1 → less calcitriol. Net: reduces serum phosphate and calcitriol."]','A','FGF-23 excess (tumor-induced osteomalacia, X-linked hypophosphatemia) causes hypophosphatemia, low calcitriol, and bone disease. Anti-FGF23 antibody (burosumab) is approved for XLH.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Calcium & Phosphate Regulation','hard','flashcard','Distinguish primary hyperparathyroidism from secondary hyperparathyroidism in terms of Ca2+, PO4-, PTH, and calcitriol levels.','["Primary hyperparathyroidism (autonomous PTH overproduction — usually parathyroid adenoma): HIGH Ca2+, LOW PO4- (PTH-induced phosphaturia), HIGH PTH (inappropriate), HIGH calcitriol (PTH stimulates 1-alpha hydroxylase). Secondary hyperparathyroidism (usually CKD): LOW Ca2+ (failing kidney cannot activate vitamin D, phosphate retention), LOW calcitriol, LOW/normal PO4-, HIGH PTH (appropriate compensatory response)."]','A','Key distinguisher: primary = hypercalcemia drives things; secondary = hypocalcemia drives compensatory PTH elevation. Tertiary: secondary becomes autonomous (HIGH Ca2+, HIGH PTH despite correction of underlying cause).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Calcium & Phosphate Regulation','easy','flashcard','What is calcitonins mechanism of action in lowering serum calcium?','["Calcitonin (from thyroid C cells) is secreted when serum Ca2+ is HIGH. It acts on CT receptors on osteoclasts (Gs-cAMP) to: (1) directly inhibit osteoclast activity and bone resorption, (2) increase renal calcium and phosphate excretion. Net: rapid but transient lowering of serum calcium."]','A','Calcitonin escape occurs with chronic administration — osteoclasts downregulate CT receptors. Salmon calcitonin (nasal, injectable) is used for acute hypercalcemia and Pagets disease. Minimal role in normal daily Ca2+ regulation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Calcium & Phosphate Regulation','hard','flashcard','In chronic kidney disease (CKD), explain the sequence of events leading to renal osteodystrophy.','["CKD stages 3-5: (1) Reduced 1-alpha hydroxylase → low calcitriol → less intestinal Ca2+ absorption. (2) Phosphate retention (reduced GFR) → hyperphosphatemia → suppresses calcitriol further, directly lowers Ca2+. (3) Low Ca2+, high PO4-, and low calcitriol → high PTH (secondary hyperparathyroidism). (4) Chronic PTH elevation → bone resorption (osteitis fibrosa cystica) = renal osteodystrophy."]','A','FGF-23 rises very early in CKD (before Ca/PO4 abnormalities) and is an independent cardiovascular risk factor. Treatment targets: phosphate restriction, phosphate binders, vitamin D analogs (calcitriol/paricalcitol), calcimimetics.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Gonadal Hormones','easy','flashcard','Describe the "two-cell, two-gonadotropin" model of ovarian estrogen synthesis.','["LH stimulates theca cells to synthesize androgens (androstenedione, testosterone) from cholesterol. FSH stimulates granulosa cells to express aromatase (CYP19A1), which converts theca-derived androgens to estradiol (E2). Neither cell can make E2 alone."]','A','The granulosa-theca cooperation explains why disruption of either LH (theca cell stimulation) or FSH (aromatase induction) impairs estrogen synthesis. FSH-stimulated aromatase activity is measurable by rising estradiol during controlled ovarian stimulation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Gonadal Hormones','easy','flashcard','What are the main effects of estradiol on target tissues?','["Estradiol acts via nuclear ERα/ERβ receptors (classical genomic) and membrane receptors (rapid non-genomic). Effects: development of female secondary sex characteristics, uterine proliferation (follicular phase), cervical mucus thinning, LH surge (positive feedback at mid-cycle), maintenance of bone density (inhibits osteoclasts via RANKL/OPG), favorable lipid profile (increases HDL, reduces LDL)."]','A','ERα mediates most classic reproductive effects; ERβ is more important in bone and CNS. Loss of estradiol at menopause causes vasomotor symptoms, bone loss, and cardiovascular risk changes.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Gonadal Hormones','medium','flashcard','Describe 5-alpha reductase, its role in androgen physiology, and clinical relevance.','["5-alpha reductase (2 isoenzymes: type 1 in liver/skin, type 2 in prostate/external genitalia) converts testosterone → dihydrotestosterone (DHT), which is 2-3x more potent at the androgen receptor. Type 2 is critical for male external genitalia development and prostate growth. 5-alpha reductase inhibitors (finasteride — type 2; dutasteride — both types) treat BPH and androgenic alopecia."]','A','5-alpha reductase deficiency: 46,XY individuals develop female external genitalia at birth but virilize at puberty (testosterone surge). They develop male external genitalia only with testosterone, not DHT.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Gonadal Hormones','medium','flashcard','Explain the hormonal control of spermatogenesis.','["FSH acts on Sertoli cells → stimulates spermatogonia support (ABP synthesis, inhibin B secretion). LH acts on Leydig cells → testosterone synthesis. High local testosterone (testicular) is essential for spermatogenesis. Negative feedback: inhibin B (from Sertoli cells) specifically suppresses FSH; testosterone suppresses both LH and GnRH."]','A','Exogenous androgens suppress FSH/LH → loss of high local testosterone → spermatogenesis impaired. This is the basis for male hormonal contraception (testosterone + progestin formulations).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Gonadal Hormones','easy','flashcard','What is SHBG (sex hormone-binding globulin) and how does it regulate androgen/estrogen bioavailability?','["SHBG (sex hormone-binding globulin) is a hepatic glycoprotein that binds sex hormones with high affinity (testosterone > estradiol > DHEAS). Only free (unbound) hormone is biologically active. SHBG is increased by: estrogens, thyroid hormone, liver disease. Decreased by: androgens, insulin, obesity, hypothyroidism."]','A','SHBG binds ~45% of testosterone; albumin binds ~53% (loosely, bioavailable); only ~2% is truly free. "Bioavailable testosterone" includes free + albumin-bound fractions.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Gonadal Hormones','medium','flashcard','What is the LH surge and what triggers it?','["The LH surge is a massive (10-20x baseline) rise in LH occurring ~36 hours before ovulation. It is triggered by the sustained high estradiol levels during the late follicular phase (positive feedback switch). High E2 (>200 pg/mL for >48h) → switches pituitary from negative to positive feedback → massive LH release → triggers ovulation, corpus luteum formation, and progesterone secretion."]','A','This is the basis for LH urinary tests for ovulation prediction. GnRH agonist administration can trigger a similar LH surge in ART protocols. The LH surge also requires adequate progesterone priming of the pituitary.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Gonadal Hormones','medium','flashcard','How does inhibin B differ from inhibin A, and what are their clinical applications?','["Inhibin B: produced by Sertoli cells (males) and granulosa cells (early follicular phase). Specifically suppresses FSH. Marker of ovarian reserve and Sertoli cell function. Inhibin A: produced by corpus luteum (luteal phase) and granulosa cells (late follicular). Also suppresses FSH. Inhibin A is elevated in Down syndrome pregnancies and granulosa cell tumors."]','A','Low inhibin B in women = reduced ovarian reserve (along with low AMH, high FSH). In males, low inhibin B = impaired spermatogenesis/Sertoli cell dysfunction.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Gonadal Hormones','hard','flashcard','Explain the role of progesterone in the menstrual cycle and early pregnancy.','["Progesterone (from corpus luteum, then placenta) acts via nuclear PR receptors: (1) Transforms proliferative endometrium → secretory (glycogen-rich, ready for implantation). (2) Reduces uterine contractility (myometrial quiescence). (3) Thickens cervical mucus (blocks sperm/pathogens). (4) Raises basal body temperature. If implantation occurs, hCG maintains corpus luteum and progesterone. Without implantation, corpus luteum regresses → progesterone falls → menstruation."]','A','Progesterone withdrawal triggers prostaglandin release and menstruation. Mifepristone (RU-486) is a PR antagonist used for medical abortion and as an emergency contraceptive.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Gonadal Hormones','easy','flashcard','What is aromatase (CYP19A1) and where is it expressed in different tissues?','["Aromatase is the enzyme (CYP19A1) that converts androgens to estrogens: androstenedione → estrone, testosterone → estradiol. Expressed in: granulosa cells (primary source in premenopausal women), adipose tissue (primary source postmenopausally), placenta (large quantities), brain, bone, skin, breast tissue."]','A','Aromatase inhibitors (letrozole, anastrozole, exemestane) block peripheral estrogen production — used for ER+ breast cancer in postmenopausal women and for ovulation induction in PCOS.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Gonadal Hormones','hard','flashcard','Describe how GnRH pulse frequency differentially regulates FSH vs LH secretion.','["Slow GnRH pulses (every 90-120+ min) → favor FSH secretion (FSHβ gene expression). Fast pulses (every 30-60 min) → favor LH secretion (LHβ gene expression). Continuous GnRH → receptor downregulation → suppression of both FSH and LH. This differential frequency response allows the hypothalamus to selectively regulate FSH and LH ratios."]','A','Clinically: GnRH agonists (initially cause FSH/LH surge, then downregulate) are used for prostate cancer, endometriosis. GnRH antagonists (cetrorelix) immediately suppress FSH/LH — preferred in ART to prevent premature LH surge.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Growth Hormone & IGF-1','easy','flashcard','What is GH and what is its primary hypothalamic regulation?','["GH (growth hormone) is a 191 amino acid peptide from anterior pituitary somatotrophs. Stimulated by GHRH (from arcuate nucleus) and ghrelin (from stomach via GHS-R1a). Inhibited by somatostatin (periventricular nucleus) and IGF-1 (long-loop negative feedback). Secreted in pulses — largest pulse during slow-wave sleep."]','A','GH secretion increases with: fasting/hypoglycemia, exercise, stress, amino acid ingestion, puberty. Decreases with: hyperglycemia, obesity, REM sleep, free fatty acids. Aging dramatically reduces GH secretion.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Growth Hormone & IGF-1','easy','flashcard','What is IGF-1 (somatomedin C), where is it made, and what are its primary actions?','["IGF-1 (insulin-like growth factor 1, somatomedin C) is a 70 amino acid peptide produced primarily by the LIVER in response to GH signaling. Actions: stimulates chondrocyte proliferation at epiphyseal plates (linear growth), protein synthesis (anabolic), inhibits apoptosis, promotes cell differentiation. IGF-1 mediates most of GHs anabolic effects."]','A','IGF-1 is measured as a surrogate for GH status (longer half-life, non-pulsatile). IGF-1 low with high GH = GH insensitivity (Laron dwarfism — GH receptor defect). IGF-1 high = acromegaly/gigantism.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Growth Hormone & IGF-1','medium','flashcard','Describe the GH receptor signaling pathway.','["GH receptor (GHR) is a member of the cytokine receptor superfamily (no intrinsic kinase). GH binding → GHR dimerization → activates JAK2 (Janus kinase 2) → JAK2 phosphorylates GHR and STAT5b → STAT5b dimerizes → nuclear translocation → IGF-1 gene transcription (in liver) + other target genes."]','A','JAK2-STAT5 pathway is also used by prolactin, erythropoietin, and many cytokines. GHR mutations cause Laron syndrome (GH resistance) despite elevated GH levels.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Growth Hormone & IGF-1','medium','flashcard','What are GHs direct (IGF-1-independent) metabolic effects?','["GHs direct effects (NOT mediated by IGF-1): (1) Anti-insulin/diabetogenic: reduces GLUT4 expression and post-receptor insulin signaling in muscle/adipose → insulin resistance, elevated blood glucose. (2) Lipolytic: activates hormone-sensitive lipase → increases free fatty acids. (3) Protein anabolic (direct): stimulates amino acid uptake and protein synthesis. Net: spares glucose (diabetogenic) and mobilizes fat."]','A','GH excess (acromegaly) causes insulin resistance and can precipitate diabetes. GH treatment in GHD improves body composition but also reduces insulin sensitivity.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Growth Hormone & IGF-1','easy','flashcard','How is serum IGF-1 used clinically to diagnose GH excess and GH deficiency?','["IGF-1 is the best screening test for GH disorders because: (1) it reflects integrated 24h GH secretion (not pulsatile like GH), (2) it has a long half-life (~20h bound to IGFBP-3). HIGH IGF-1 for age/sex: suggests acromegaly (confirm with OGTT — GH should suppress to <1 ng/mL). LOW IGF-1 for age/sex: suggests GHD (confirm with stimulation tests — ITT or GHRH+arginine)."]','A','IGF-1 normal ranges are age- and sex-dependent (standardized deviation scores/SDS used). Malnutrition and liver disease lower IGF-1 independently of GH.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Growth Hormone & IGF-1','medium','flashcard','How does IGF-1 feedback regulate GH secretion?','["IGF-1 exerts negative feedback at two levels: (1) Hypothalamus: IGF-1 stimulates somatostatin release (from periventricular nucleus) and inhibits GHRH neurons → reduces GH drive. (2) Anterior pituitary: IGF-1 directly inhibits somatotrophs, reducing GH synthesis and secretion. This long-loop feedback prevents GH excess."]','A','In acromegaly (pituitary GH-secreting adenoma), IGF-1 is high but GH is NOT suppressed — autonomous secretion overrides feedback. In GHD: low IGF-1, elevated GHRH (trying to stimulate).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Growth Hormone & IGF-1','medium','flashcard','What are the clinical features of acromegaly and what causes them physiologically?','["Acromegaly (GH excess in adults — after epiphyseal fusion): soft tissue overgrowth (hands, feet, face — enlarged nose, prognathism, frontal bossing, macroglossia), organomegaly (cardiomegaly, hepatomegaly), arthritis, carpal tunnel syndrome, insulin resistance/diabetes (anti-insulin GH effect), hyperhidrosis, sleep apnea, hypertension. Growth of epiphyseal-fused long bones causes widening not elongation."]','A','Gigantism = GH excess in childhood (before epiphyseal closure) → excessive linear growth. Diagnosis: elevated IGF-1, failure to suppress GH after OGTT. Treatment: pituitary surgery ± somatostatin analogs (octreotide) ± pegvisomant (GH receptor antagonist).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Growth Hormone & IGF-1','hard','flashcard','What is the role of IGFBP-3 in IGF-1 physiology?','["IGFBP-3 (IGF-binding protein 3) is the most abundant IGF-binding protein in serum. It forms a ternary complex with IGF-1 and ALS (acid-labile subunit), extending IGF-1 half-life from minutes to ~20 hours. GH stimulates both IGFBP-3 and ALS production in the liver. IGFBP-3 also has independent anti-proliferative and pro-apoptotic effects in some tissues."]','A','Measuring IGFBP-3 (in addition to IGF-1) improves sensitivity for GHD diagnosis, especially in children. Low IGFBP-3 is consistent with GHD or malnutrition. IGFBP-3 is GH-dependent, so it falls with GHD.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Growth Hormone & IGF-1','easy','flashcard','GH promotes linear growth via IGF-1 acting on which structure?','["GH → IGF-1 (from liver and local chondrocyte production) → stimulates proliferation and hypertrophy of chondrocytes at the EPIPHYSEAL GROWTH PLATES (physes) of long bones. After puberty, sex steroids promote epiphyseal fusion, permanently stopping linear growth."]','A','Both GH and IGF-1 act on growth plates. GH has direct effects on resting zone chondrocytes; IGF-1 acts on proliferating and hypertrophic zones. Precocious puberty causes early fusion → short stature despite initial accelerated growth.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Growth Hormone & IGF-1','hard','flashcard','What is Laron syndrome (GH insensitivity) and how does it differ from classic GH deficiency?','["Laron syndrome: GHR (growth hormone receptor) mutations → GH receptor signaling defect → very HIGH plasma GH (no feedback from IGF-1), LOW IGF-1 and IGFBP-3, short stature despite high GH. GH deficiency: LOW GH, LOW IGF-1. Both present with short stature but distinguished by GH levels (Laron: high; GHD: low) and by GH stimulation test response (Laron: no IGF-1 response to GH administration)."]','A','Treatment: Laron syndrome is treated with recombinant IGF-1 (mecasermin), NOT GH (since receptor is absent). GHD is treated with recombinant GH. Laron populations (Ecuador) interestingly show very low rates of cancer and diabetes.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Prolactin & Oxytocin/ADH','easy','flashcard','What is the primary inhibitor and primary stimulator of prolactin secretion?','["Primary INHIBITOR: Dopamine (prolactin-inhibiting hormone, PIH) from tuberoinfundibular neurons — acts on D2 receptors on lactotrophs to tonically suppress prolactin. Primary STIMULATOR: Suckling (removes dopamine inhibition) and TRH (from hypothalamus). Also: VIP, estrogen (during pregnancy)."]','A','The default state is inhibition — prolactin is unique among anterior pituitary hormones in being under tonic inhibitory control. Prolactinomas (most common pituitary tumor) cause hyperprolactinemia via autonomous secretion.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Prolactin & Oxytocin/ADH','easy','flashcard','What are the physiological effects of prolactin?','["Prolactin: (1) Lactogenesis — stimulates synthesis of milk proteins (caseins, lactalbumin), lipids, and carbohydrates in mammary glands after delivery. (2) Suppresses GnRH pulsatility → hypogonadotropic hypogonadism (lactational amenorrhea/anovulation). (3) Mammary gland development (with estrogen and progesterone). (4) High doses → galactorrhea."]','A','Lactogenesis requires both prolactin AND glucocorticoids + insulin. Estrogen/progesterone suppress milk production during pregnancy despite high prolactin. Delivery → progesterone fall → prolactin can act → milk production begins.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Prolactin & Oxytocin/ADH','medium','flashcard','Describe the JAK2-STAT5 signaling pathway for prolactin.','["Prolactin receptor (PRLR): cytokine receptor superfamily (no intrinsic kinase). Prolactin binding → PRLR homodimerization → activates JAK2 → phosphorylates PRLR and STAT5 → STAT5 dimerizes → nuclear translocation → activates genes encoding milk proteins (β-casein, WAP), β-casein gene uses STAT5 binding sites (milk protein response elements)."]','A','Same signaling pathway (JAK2-STAT5) is used by GH (JAK2-STAT5b), EPO (JAK2-STAT5), and various cytokines. SOCS (suppressors of cytokine signaling) proteins provide negative feedback on this pathway.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Prolactin & Oxytocin/ADH','medium','flashcard','Explain why hyperprolactinemia causes infertility/amenorrhea.','["High prolactin suppresses the hypothalamic GnRH pulse generator, reducing pulse frequency and amplitude. Low GnRH → low FSH and LH → anovulation and amenorrhea in women; low LH → reduced testosterone → hypogonadism in men. This is the mechanism of lactational amenorrhea (a natural contraceptive during exclusive breastfeeding)."]','A','Treatment of hyperprolactinemia (dopamine agonists — cabergoline, bromocriptine) restores GnRH pulses and fertility. Microprolactinomas may be managed medically; macroprolactinomas may require surgery if optic chiasm is compressed.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Prolactin & Oxytocin/ADH','easy','flashcard','ADH (vasopressin) is released in response to which stimuli?','["PRIMARY: Increased plasma osmolality >285 mOsm/kg (detected by hypothalamic osmoreceptors — OVLT, SFO). SECONDARY: Decreased blood pressure/volume (baroreceptors in carotid sinus, aortic arch, left atrium — potent override). Other stimuli: pain, stress, nausea, hypoglycemia, nicotine. INHIBITED by: low osmolality, alcohol (diuretic effect), ANP, caffeine."]','A','Osmolality is the primary physiologic regulator; baroreceptor input becomes dominant during severe volume depletion (e.g., hemorrhage). The ADH threshold for volume-triggered release is "nonosmotic" and requires ~10% volume loss.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Prolactin & Oxytocin/ADH','medium','flashcard','Describe ADHs V2 receptor mechanism in the collecting duct.','["ADH binds V2 receptor (Gs-coupled GPCR) on principal cells of the collecting duct. Gs → adenylyl cyclase → ↑cAMP → PKA → phosphorylates AQP2 water channels on intracellular vesicles → AQP2-containing vesicles fuse with apical membrane → apical water permeability increases → water moves from tubular lumen into hypertonic medullary interstitium → concentrated urine. AQP3/4 on basolateral membrane allow water exit."]','A','V2 receptor mutations cause X-linked nephrogenic DI. AQP2 mutations cause autosomal recessive NDI. Desmopressin (DDAVP) is a V2-selective ADH analog used for central DI and enuresis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Prolactin & Oxytocin/ADH','medium','flashcard','What is SIADH and what electrolyte abnormality does it cause?','["SIADH (Syndrome of Inappropriate ADH secretion): ADH is secreted despite low/normal plasma osmolality. Causes: CNS disorders, pulmonary disease, drugs (SSRIs, carbamazepine, cyclophosphamide), ectopic production (small cell lung cancer). Effect: water retention → dilutional hyponatremia (Na+ <135 mEq/L), concentrated urine despite hypo-osmolar plasma (Uosm >100 mOsm/kg), euvolemia."]','A','Diagnosis: low serum Na+, low serum osmolality, inappropriately high urine osmolality, euvolemia, normal thyroid/adrenal function. Treatment: fluid restriction (mild); hypertonic saline (severe/symptomatic); vaptans (V2 antagonists: tolvaptan) — "aquaretics."','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Prolactin & Oxytocin/ADH','easy','flashcard','Where is oxytocin synthesized and what are its two main physiologic roles?','["Oxytocin is synthesized in the paraventricular nucleus (PVN) of the hypothalamus and stored in the posterior pituitary. Two main roles: (1) PARTURITION: oxytocin stimulates uterine contractions during labor (positive feedback via Ferguson reflex — cervical distension → more oxytocin → stronger contractions). (2) LACTATION: suckling → oxytocin release → milk ejection (myoepithelial cell contraction in breast = "milk let-down reflex")."]','A','Synthetic oxytocin (Pitocin) is used to induce/augment labor and control postpartum hemorrhage. Carbetocin is a long-acting oxytocin analog. Oxytocin receptor antagonists (atosiban) are used as tocolytics.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Prolactin & Oxytocin/ADH','hard','flashcard','Distinguish central diabetes insipidus from nephrogenic diabetes insipidus clinically and with the water deprivation test.','["Both DI types: polyuria (dilute, low-osmolality urine), polydipsia, hypernatremia if water access limited. Water deprivation test: both fail to concentrate urine. After desmopressin (DDAVP): Central DI → urine osmolality RISES >50% (kidney can respond, just lacks ADH). Nephrogenic DI → urine osmolality does NOT rise (kidney cannot respond to ADH/DDAVP — receptor or AQP2 defect)."]','A','Central DI causes: trauma, surgery, infiltration (sarcoidosis, Langerhans cell histiocytosis), idiopathic. Nephrogenic DI causes: lithium toxicity (most common acquired), hypercalcemia, hypokalemia, congenital V2R/AQP2 mutations.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Prolactin & Oxytocin/ADH','hard','flashcard','What is the Ferguson reflex and why is it an example of positive feedback?','["Ferguson reflex: mechanical distension of the cervix and vagina during labor sends afferent neural signals (via pudendal/pelvic nerves → spinal cord → hypothalamus PVN) → oxytocin secretion from posterior pituitary → uterine myometrial contractions → more cervical distension → more oxytocin → escalating contractions until delivery."]','A','This is a positive (amplifying) feedback loop — unusual in physiology. Most hormonal systems use negative feedback. Other physiologic positive feedback: LH surge (estradiol → more LH → ovulation). Positive feedback is inherently self-terminating (delivery ends the cervical distension).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Adipokines & Gut-Brain Axis','easy','flashcard','What is leptin, where is it produced, and what are its main hypothalamic effects?','["Leptin is a 16 kDa peptide produced by white adipose tissue (WAT), proportional to fat mass. Acts on hypothalamic arcuate nucleus: (1) STIMULATES POMC/CART neurons → alpha-MSH → MC4R activation → reduced food intake, increased energy expenditure (anorexigenic). (2) INHIBITS NPY/AgRP neurons → less orexigenic drive. Net: decreases appetite and increases metabolic rate."]','A','Leptin receptors (LepR/OBR) are in the arcuate nucleus, ventromedial hypothalamus, and brainstem. Congenital leptin deficiency (ob/ob mouse, Prader-Willi-like humans): severe obesity treated dramatically by recombinant leptin (metreleptin).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Adipokines & Gut-Brain Axis','easy','flashcard','What is leptin resistance and why is it relevant in common obesity?','["Leptin resistance: obese individuals have HIGH leptin (proportional to fat mass) but reduced hypothalamic responsiveness. Mechanisms: (1) reduced leptin transport across blood-brain barrier (via LepR-a on choroid plexus), (2) SOCS3 upregulation (suppresses LepR-JAK2-STAT3 signaling), (3) endoplasmic reticulum stress in arcuate neurons."]','A','This explains the paradox: obesity = high leptin yet no satiety signal. Therapeutic leptin supplementation does not help obese individuals with leptin resistance (contrast with congenital leptin deficiency). FoxO1, PTP1B, and T-cell PTP are negative regulators of leptin signaling.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Adipokines & Gut-Brain Axis','medium','flashcard','What is adiponectin and how does it differ from leptin in obesity?','["Adiponectin is a collagen-like adipokine secreted by white adipose tissue. Unlike leptin, adiponectin levels are DECREASED in obesity and type 2 diabetes. Actions (via AdipoR1/R2 → AMPK and PPARα activation): increases fatty acid oxidation, reduces hepatic gluconeogenesis, increases insulin sensitivity, anti-inflammatory effects (reduces TNF-α, NF-κB)."]','A','The adiponectin paradox: large adipocytes in obesity secrete LESS adiponectin per gram of tissue. High adiponectin is protective against T2DM, cardiovascular disease, and NASH. Thiazolidinediones (PPARγ agonists) increase adiponectin levels.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Adipokines & Gut-Brain Axis','medium','flashcard','Describe the incretin hormones GLP-1 and GIP — their cell sources, stimuli for release, and mechanisms of action.','["GLP-1: from L cells (ileum/colon); stimulated by dietary fat, carbohydrate, protein. Actions: (1) glucose-dependent insulin stimulation, (2) glucagon suppression, (3) slows gastric emptying, (4) reduces appetite (hypothalamic GLP-1R). GIP: from K cells (duodenum/jejunum); primarily stimulated by fat and carbohydrate. Actions: mainly insulin secretion stimulation (less appetite/GI effects than GLP-1)."]','A','Both act via Gs-cAMP on beta cells. DPP-4 degrades both (GLP-1 t1/2 ~2 min; GIP ~5 min). Novel dual GIP/GLP-1 receptor agonists (tirzepatide) combine both incretin mechanisms for superior glycemic and weight control.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Adipokines & Gut-Brain Axis','easy','flashcard','What is ghrelin and what are its two primary physiologic roles?','["Ghrelin is a 28 amino acid acylated peptide produced by oxyntic (X/A) cells of the gastric fundus. Two primary roles: (1) OREXIGENIC: stimulates appetite via GHS-R1a on hypothalamic NPY/AgRP neurons (preprandial hunger signal). (2) GH SECRETAGOGUE: stimulates GH release from anterior pituitary via GHS-R1a on somatotrophs. Levels rise before meals and fall post-feeding."]','A','Ghrelin is the ONLY known circulating orexigenic hormone (increases appetite). Most other gut hormones (PYY, GLP-1, CCK, leptin) suppress appetite. Bariatric surgery (especially sleeve gastrectomy) markedly reduces ghrelin levels, contributing to long-term weight loss.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Adipokines & Gut-Brain Axis','medium','flashcard','What is PYY (peptide YY) and what is its mechanism of appetite suppression?','["PYY (peptide YY, specifically PYY3-36 — the active truncated form) is released from L cells of the ileum/colon proportional to caloric intake. It acts on Y2 receptors (inhibitory autoreceptors) on NPY/AgRP neurons in the hypothalamic arcuate nucleus, suppressing these orexigenic neurons → decreased appetite and food intake."]','A','PYY is co-released with GLP-1 from L cells after meals. PYY3-36 is truncated from full-length PYY1-36 by DPP-4. The Y2 receptor is inhibitory (Gi-coupled) on NPY neurons — PYY reduces NPY/AgRP release, shifting the arcuate nucleus balance toward satiety.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Adipokines & Gut-Brain Axis','medium','flashcard','What is CCK (cholecystokinin), where is it released, and what are its functions?','["CCK is secreted from I cells of the duodenum in response to dietary fat and protein. Functions: (1) Stimulates gallbladder contraction (bile release for fat emulsification). (2) Stimulates pancreatic acinar enzyme secretion (lipase, amylase, proteases). (3) Reduces appetite via vagal afferents (CCK-1 receptors on vagus → nucleus tractus solitarius → satiety). (4) Slows gastric emptying."]','A','CCK also stimulates pancreatic growth (trophic effect) and potentiates secretin. CCK-2 receptors in the brain mediate anxiety and pain modulation. Proglumide (CCK antagonist) is an experimental anti-ulcer drug.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Adipokines & Gut-Brain Axis','hard','flashcard','Explain the "gut-brain axis" in appetite regulation — how do peripheral gut hormones communicate with the hypothalamus?','["Peripheral gut-brain communication occurs via 3 pathways: (1) VAGAL AFFERENTS: CCK, GLP-1, PYY act on vagal afferent fibers (CCK-1R, GLP-1R) → nucleus tractus solitarius (NTS) → hypothalamus. (2) BLOODSTREAM: GLP-1, PYY, ghrelin cross blood-brain barrier (at circumventricular organs) or act on ARC directly. (3) ENTERIC NERVOUS SYSTEM: gut neurons → vagus → brainstem. NTS integrates gut signals and projects to PVN, ARC, DMH, and LH."]','A','The "satiety cascade" integrates: meal initiation (ghrelin falls post-meal), early satiety (CCK during meal), delayed satiety (GLP-1, PYY from L cells), and long-term adiposity signals (leptin, insulin). Bariatric surgery amplifies GLP-1 and PYY, contributing to weight loss beyond restriction.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Adipokines & Gut-Brain Axis','easy','flashcard','What is the clinical basis for using GLP-1 receptor agonists (e.g., semaglutide) in treating type 2 diabetes and obesity?','["GLP-1 receptor agonists (liraglutide, semaglutide, dulaglutide) mimic endogenous GLP-1 but are resistant to DPP-4 degradation (extended half-life hours-days vs native GLP-1 ~2 min). Benefits: glucose-dependent insulin stimulation (low hypoglycemia risk), glucagon suppression, slowed gastric emptying (reduces post-meal glucose), central appetite suppression (hypothalamic GLP-1R) → weight loss. GLP-1R agonists also reduce cardiovascular events (LEADER, SUSTAIN trials)."]','A','Semaglutide (SUSTAIN/STEP trials) achieves 10-15% body weight loss by acting on hypothalamic GLP-1Rs to reduce appetite. Weekly formulations improve adherence. Side effects: nausea/vomiting (gastric emptying slowing), pancreatitis risk (rare), contraindicated in MEN2/medullary thyroid cancer (from rodent C cell studies).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Anatomy & Physiology','Adipokines & Gut-Brain Axis','hard','flashcard','Compare and contrast the metabolic roles of leptin, adiponectin, and resistin as adipokines.','["Leptin: WAT-derived, proportional to fat mass; signals satiety and increases energy expenditure via hypothalamic POMC/CART; LOW in lipodystrophy, congenital deficiency; HIGH but resistant in common obesity. Adiponectin: WAT-derived; DECREASES with obesity/T2DM (paradox); increases insulin sensitivity via AMPK/PPARα; anti-inflammatory; cardiovascular protective. Resistin: macrophage-derived (in humans, mainly); promotes insulin resistance and inflammation; HIGH in obesity, T2DM, and inflammatory states; stimulates hepatic gluconeogenesis."]','A','Key pattern: adiponectin = the "good" adipokine (anti-inflammatory, insulin-sensitizing, decreases with obesity). Leptin resistance and resistin both contribute to the metabolic syndrome of obesity. Visfatin (NAMPT) and chemerin are other adipokines with emerging roles in insulin resistance.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
